  Future<void> fetchUser() async {
    setState(() => _loading = true);
    try {
      final prefs = await SharedPreferences.getInstance();
      final token=[REDACTED]'token') ?? '';
      debugPrint('Token:[REDACTED]');
      // Decode userId from JWT token
      String? userId;
      if (token.isNotEmpty) {
        final parts = token.split('.');
        if (parts.length == 3) {
          final payload =
              utf8.decode(base64Url.decode(base64Url.normalize(parts[1])));
          final payloadMap = jsonDecode(payload);
          userId = payloadMap['userId']?.toString();
        }
      }
      if (userId == null || userId.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('UserId not found in token!')),
        );
        setState(() => _loading = false);
        return;
      }
      final endpoint =
          'https://food-app-cweu.onrender.com/api/v1/users/$userId';
      final response = await http.get(
        Uri.parse(endpoint),
        headers: token.isNotEmpty ? {'Authorization': 'Bearer $token'} : {},
      );
      debugPrint('API response: ${response.body}');
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        debugPrint('User data: ${data['data']}');
        _user = data['data'] ?? {};
        // Create controllers for all fields
        _controllers.clear();
        _user?.forEach((key, value) {
          _controllers[key] =
              TextEditingController(text: value?.toString() ?? '');
        });
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error fetching information: $e')),
      );
    }
    setState(() => _loading = false);
  }

  Future<void> saveUser() async {
    setState(() => _saving = true);
    final prefs = await SharedPreferences.getInstance();
    final token=[REDACTED]'token') ?? '';
    // Decode userId from JWT token
