      currentTemplate = this.value;
      await renderFields();
      await syncCardStyleToPreviewFrame(currentTemplate);
      setPreviewSide(currentSide);
    });
    ```

## 2. Field Input Area (fieldGrid)

- **Location**: form.html
  ```html
  <div class="field-grid" id="fieldGrid"></div>
  ```
- **Logic**: form.js
  - `renderFields()` obtains field names and default values via `/scan_fields` and `/load_fields`, generating a button for each field:
    ```js
    fields.forEach(field => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'field-btn';
      btn.textContent = field;
      btn.dataset.field = field;
      if (allFieldData[field]) btn.classList.add('filled');
      btn.onclick = function(e) { showFieldInput(field, btn); };
      fieldGrid.appendChild(btn);
    });
    ```
  - Buttons with the `.filled` class indicate content has been entered.

## 3. Floating Input Box

- **Location**: form.html
  ```html
