    document.getElementById('backBtn').onclick = function() { setPreviewSide('back'); };
    function setPreviewSide(side) {
      currentSide = side;
      document.getElementById('sideInput').value = side;
      document.getElementById('frontBtn').classList.toggle('active', side === 'front');
      document.getElementById('backBtn').classList.toggle('active', side === 'back');
      document.getElementById('ankiForm').action = `/preview/${side}?tpl=${currentTemplate}`;
      syncFieldsToForm();
      document.getElementById('ankiForm').submit();
    }
    ```

## 5. Refresh/Clear/Save Buttons

- **Refresh Preview** (refresh iframe):
  ```html
  <button class="btn" type="submit" id="refreshBtn">Refresh Preview</button>
  ```
  - Bind event, prevent default submission, manually sync fields and submit the form:
    ```js
    document.getElementById('refreshBtn').onclick = function(e) {
      e.preventDefault();
      syncFieldsToForm();
      document.getElementById('ankiForm').submit();
    };
    ```

- **Clear Content**:
  ```html
  <button class="btn" type="button" onclick="clearForm()" style="background:#e74c3c;">Clear Content</button>
  ```
  - Clear all field contents, reset allFieldData, and refresh the preview:
    ```js
    function clearForm() {
      var t = document.querySelectorAll('.form-panel textarea');
      t.forEach(e => e.value = '');
      allFieldData = {};
      updateFieldStatus();
      setTimeout(() => setPreviewSide(currentSide), 10);
    }
    ```

- **Save Data** (to server):
  ```html
  <button class="btn" type="button" id="saveServerBtn" style="background:#f39c12;">Save Data</button>
  ```
  - Send a POST request to `/save_fields` to save the current field data to the server:
    ```js
    document.getElementById('saveServerBtn').onclick = async function() {
      await fetch(`/save_fields?tpl=${currentTemplate}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
