To switch to the MyBatis framework, you need to modify the implementation according to the following steps:

1. First, add the dependency to pom.xml:

<dependency>
    <groupId>org.mybatis.spring.boot</groupId>
    <artifactId>mybatis-spring-boot-starter</artifactId>
    <version>3.0.3</version>
</dependency>

2. Change the repository interface to a MyBatis mapper:

package com.example.demo_caser.repository;

import java.util.List;

import org.apache.ibatis.annotations.Delete;
import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Options;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;

import com.example.demo_caser.model.Todo;

@Mapper
public interface TodoRepository {

    @Select("SELECT * FROM todos")
    List<Todo> findAll();

    @Select("SELECT * FROM todos WHERE id = #{id}")
    Todo findById(@Param("id") Long id);

    @Insert("INSERT INTO todos(title, completed, created_at) VALUES(#{title}, #{completed}, #{createdAt})")
    @Options(useGeneratedKeys=[REDACTED] keyProperty = "id")
    int save(Todo todo);

    @Update("UPDATE todos SET title = #{title}, completed = #{completed} WHERE id = #{id}")
    int update(Todo todo);

    @Delete("DELETE FROM todos WHERE id = #{id}")
    int deleteById(@Param("id") Long id);
}

3. Modification of the Todo entity (removal of JPA-specific annotations):

package com.example.demo_caser.model;

import java.time.LocalDateTime;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class Todo {
    private Long id;
    private String title;
    private boolean completed;
    private LocalDateTime createdAt;

    public Todo(String title) {
        this.title = title;
        this.completed = false;
        this.createdAt = LocalDateTime.now();
    }
}

4. Add MyBatis configuration to application.properties:
```
# MyBatis configuration
mybatis.configuration.map-underscore-to-camel-case=true
mybatis.type-aliases-package=com.example.demo_caser.model
```

5. Update the service class (if necessary):

package com.example.demo_caser.service;

import java.util.List;

import org.springframework.stereotype.Service;

import com.example.demo_caser.model.Todo;
import com.example.demo_caser.repository.TodoRepository;

@Service
public class TodoService {

    private final TodoRepository todoRepository;

    public TodoService(TodoRepository todoRepository) {
        this.todoRepository = todoRepository;
    }

    public List<Todo> getAllTodos() {
        return todoRepository.findAll();
    }

    public Todo getTodoById(Long id) {
        return todoRepository.findById(id);
    }

    public Todo createTodo(String title) {
        Todo todo = new Todo(title);
        todoRepository.save(todo);
        return todo;
    }

    public Todo updateTodo(Long id, String title, Boolean completed) {
        Todo todo = todoRepository.findById(id);
        if (todo != null) {
            if (title != null) {
                todo.setTitle(title);
            }
            if (completed != null) {
                todo.setCompleted(completed);
            }
            todoRepository.update(todo);
            return todo;
        }
        return null;
    }

    public void deleteTodo(Long id) {
        todoRepository.deleteById(id);
    }
}

With this, you can change the Todo application to use MyBatis. Since MyBatis allows you to write SQL directly, it is suitable when complex queries or fine-grained control are needed.

